<script setup lang="ts">
useHead({ title: 'Contact | Bookshelf' })

const values = useState<ContactValues>('contact-values', () => ({ name: '', email: '', message: '' }))
const errors = useState<ContactErrors>('contact-errors', () => ({}))
const success = useState<string | null>('contact-success', () => null)
const sending = ref(false)

// Without JavaScript the form posts here; the server checks it and renders the result.
if (import.meta.server) {
  const event = useRequestEvent()
  if (event && event.method === 'POST') {
    const body = await readBody(event).catch(() => ({}))
    const submitted = contactValuesFrom(body)
    const found = validateContact(submitted)
    if (Object.keys(found).length > 0) {
      values.value = submitted
      errors.value = found
      success.value = null
      setResponseStatus(event, 422)
    }
    else {
      values.value = { name: '', email: '', message: '' }
      errors.value = {}
      success.value = successMessage(submitted.name)
    }
  }
}

async function onSubmit() {
  const found = validateContact(values.value)
  errors.value = found
  success.value = null
  if (Object.keys(found).length > 0) return

  sending.value = true
  try {
    const result = await $fetch('/api/contact', { method: 'POST', body: values.value })
    if (result.ok) {
      success.value = result.message
      values.value = { name: '', email: '', message: '' }
    }
  }
  catch (error: unknown) {
    const data = (error as { data?: { errors?: ContactErrors } }).data
    errors.value = data?.errors ?? { message: 'Your message could not be sent. Please try again.' }
  }
  finally {
    sending.value = false
  }
}
</script>

