cat > app/composables/useFavorites.ts <<'EOF'
const STORAGE_KEY = 'bookshelf:favorites'

function readStored(): string[] {
  try {
    const value = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]')
    return Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string') : []
  }
  catch {
    return []
  }
}

/**
 * Favorite book slugs, kept in `localStorage`. The list is empty during
 * server rendering and is loaded from the browser once the page is mounted.
 */
export function useFavorites() {
  const favorites = useState<string[]>('favorites', () => [])
  const loaded = useState('favorites-loaded', () => false)

  onMounted(() => {
    if (!loaded.value) {
      favorites.value = readStored()
      loaded.value = true
    }
  })

  function isFavorite(slug: string) {
    return favorites.value.includes(slug)
  }

  function toggle(slug: string) {
    const current = readStored()
    favorites.value = current.includes(slug)
      ? current.filter(item => item !== slug)
      : [...current, slug]
    localStorage.setItem(STORAGE_KEY, JSON.stringify(favorites.value))
    loaded.value = true
  }

  return { favorites, loaded, isFavorite, toggle }
}
