<script setup lang="ts">
useHead({ title: 'Books | Bookshelf' })

const { data: books } = await useAsyncData('books', async () => {
  const all = await queryCollection('books').select('path', 'title', 'author', 'year', 'tags').all()
  return all.sort(byTitle)
})

const { isFavorite } = useFavorites()

const tags = computed(() => {
  const set = new Set((books.value ?? []).flatMap(book => book.tags))
  return [...set].sort((a, b) => a.localeCompare(b, 'en'))
})

const selected = ref<string | null>(null)

const visibleBooks = computed(() => {
  const list = books.value ?? []
  const tag = selected.value
  return tag === null ? list : list.filter(book => book.tags.includes(tag))
})
</script>

<template>
  <div>
    <h1>All books</h1>
    <div role="group" aria-label="Filter by tag" class="tag-filter">
      <button
        type="button"
        :aria-pressed="selected === null ? 'true' : 'false'"
        @click="selected = null"
      >
        All
      </button>
      <button
        v-for="tag in tags"
        :key="tag"
        type="button"
        :aria-pressed="selected === tag ? 'true' : 'false'"
        @click="selected = tag"
      >
        {{ tag }}
      </button>
    </div>
    <ul aria-label="Books" class="book-list">
      <li v-for="book in visibleBooks" :key="book.path">
        <NuxtLink :to="book.path">{{ book.title }}</NuxtLink>
        <span>{{ book.author }}, {{ book.year }}</span>
